package com.gamehub.application.controller; import com.gamehub.application.service.ReservationService; import java.time.Instant; import java.util.List; public final class ReservationController {private final ReservationService service;public ReservationController(ReservationService s){service=s;}public long reserve(long c,long st,Instant a,Instant b)throws Exception{return service.reserve(c,st,a,b);}public List<String> available(Instant a,Instant b)throws Exception{return service.available(a,b);}public List<String> mine(long c)throws Exception{return service.mine(c);}public void cancel(long c,long id)throws Exception{service.cancel(c,id);}}